⣾  Connecting to database
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS channels (
    channel_id   TEXT PRIMARY KEY,
    genre        TEXT NOT NULL,
    display_name TEXT NOT NULL,
    source       TEXT NOT NULL,
    source_ref   TEXT,
    added_date   TEXT NOT NULL
, last_catalog_sync TEXT, last_known_video_count INTEGER);
CREATE TABLE IF NOT EXISTS songs (
    song_id         INTEGER PRIMARY KEY AUTOINCREMENT,
    channel_id      TEXT NOT NULL REFERENCES channels(channel_id),
    canonical_title TEXT NOT NULL,
    grouped_at      TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS videos (
    video_id      TEXT PRIMARY KEY,
    channel_id    TEXT NOT NULL REFERENCES channels(channel_id),
    title         TEXT NOT NULL,
    url           TEXT NOT NULL,
    published_at  TEXT NOT NULL,
    discovered_at TEXT NOT NULL
, song_id INTEGER REFERENCES songs(song_id));
CREATE TABLE IF NOT EXISTS view_snapshots (
    video_id      TEXT NOT NULL REFERENCES videos(video_id),
    snapshot_date TEXT NOT NULL,
    views         INTEGER NOT NULL,
    PRIMARY KEY (video_id, snapshot_date)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_videos_channel ON videos(channel_id);
CREATE INDEX idx_videos_song ON videos(song_id);
CREATE INDEX idx_snapshots_date ON view_snapshots(snapshot_date);
CREATE INDEX idx_channels_genre ON channels(genre);
CREATE INDEX idx_songs_channel ON songs(channel_id);
COMMIT;
